/* ============================================
   ChartPulse Design System
   Dark-mode financial dashboard
   ============================================ */

/* ── 1. Primitive Tokens (OKLCH) ── */
:root {
  /* Brand colors in OKLCH */
  --cp-blue-50:  oklch(95% 0.03 255);
  --cp-blue-100: oklch(90% 0.06 255);
  --cp-blue-200: oklch(80% 0.12 255);
  --cp-blue-300: oklch(70% 0.18 255);
  --cp-blue-400: oklch(62% 0.22 255);
  --cp-blue-500: oklch(55% 0.24 255);
  --cp-blue-600: oklch(48% 0.22 255);
  --cp-blue-700: oklch(40% 0.18 255);
  --cp-blue-800: oklch(32% 0.14 255);
  --cp-blue-900: oklch(24% 0.10 255);

  --cp-red-400:  oklch(65% 0.22 25);
  --cp-red-500:  oklch(58% 0.24 25);
  --cp-red-600:  oklch(50% 0.22 25);

  --cp-green-400: oklch(70% 0.20 145);
  --cp-green-500: oklch(62% 0.22 145);
  --cp-green-600: oklch(54% 0.20 145);

  /* Neutral scale (cool grey) */
  --cp-grey-0:   oklch(100% 0.005 255);
  --cp-grey-50:  oklch(97% 0.01 255);
  --cp-grey-100: oklch(90% 0.015 255);
  --cp-grey-200: oklch(80% 0.02 255);
  --cp-grey-300: oklch(70% 0.025 255);
  --cp-grey-400: oklch(60% 0.03 255);
  --cp-grey-500: oklch(50% 0.03 255);
  --cp-grey-600: oklch(40% 0.025 255);
  --cp-grey-700: oklch(30% 0.02 255);
  --cp-grey-800: oklch(22% 0.015 255);
  --cp-grey-850: oklch(18% 0.012 255);
  --cp-grey-900: oklch(14% 0.01 255);
  --cp-grey-950: oklch(10% 0.008 255);

  /* ── 2. Semantic Tokens ── */
  --color-bg-primary:   var(--cp-grey-950);
  --color-bg-secondary: var(--cp-grey-900);
  --color-bg-tertiary:  var(--cp-grey-850);
  --color-bg-elevated:  var(--cp-grey-800);
  --color-bg-surface:   var(--cp-grey-700);

  --color-text-primary:   var(--cp-grey-0);
  --color-text-secondary: var(--cp-grey-200);
  --color-text-muted:     var(--cp-grey-400);
  --color-text-inverse:   var(--cp-grey-950);

  --color-accent:       var(--cp-blue-400);
  --color-accent-hover: var(--cp-blue-300);
  --color-accent-active:var(--cp-blue-500);

  --color-positive: var(--cp-green-500);
  --color-negative: var(--cp-red-500);

  --color-border:       oklch(22% 0.015 255);
  --color-border-hover: oklch(35% 0.02 255);

  /* ── 3. Typography ── */
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "JetBrains Mono", "Fira Code", "SF Mono", ui-monospace, monospace;

  --text-xs:   clamp(0.65rem, 0.6rem + 0.2vw, 0.75rem);
  --text-sm:   clamp(0.75rem, 0.7rem + 0.2vw, 0.875rem);
  --text-base: clamp(0.875rem, 0.8rem + 0.25vw, 1rem);
  --text-lg:   clamp(1rem, 0.9rem + 0.35vw, 1.125rem);
  --text-xl:   clamp(1.25rem, 1rem + 0.8vw, 1.5rem);
  --text-2xl:  clamp(1.5rem, 1.1rem + 1.5vw, 2rem);
  --text-3xl:  clamp(1.75rem, 1.2rem + 2.2vw, 2.5rem);
  --text-4xl:  clamp(2rem, 1.3rem + 3vw, 3rem);

  /* ── 4. Spacing ── */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;

  /* ── 5. Radii ── */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;

  /* ── 6. Shadows ── */
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.3);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.4);
  --shadow-lg: 0 8px 24px oklch(0% 0 0 / 0.5);

  /* ── 7. Transitions ── */
  --transition-fast: 120ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;
}

/* ── Reset ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: 1.5;
  color: var(--color-text-primary);
  background: var(--color-bg-primary);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img, picture, video, canvas, svg { display: block; max-width: 100%; }
input, button, textarea, select { font: inherit; color: inherit; }
button { cursor: pointer; background: none; border: none; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
table { border-collapse: collapse; width: 100%; }

/* ── Utility Classes ── */
.container {
  width: 100%;
  max-width: 1400px;
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-1 { gap: var(--space-1); }
.gap-2 { gap: var(--space-2); }
.gap-3 { gap: var(--space-3); }
.gap-4 { gap: var(--space-4); }
.gap-6 { gap: var(--space-6); }

.grid { display: grid; }
.grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
.grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid-cols-4 { grid-template-columns: repeat(4, 1fr); }

.text-xs   { font-size: var(--text-xs); }
.text-sm   { font-size: var(--text-sm); }
.text-base { font-size: var(--text-base); }
.text-lg   { font-size: var(--text-lg); }
.text-xl   { font-size: var(--text-xl); }
.text-2xl  { font-size: var(--text-2xl); }
.text-3xl  { font-size: var(--text-3xl); }
.text-4xl  { font-size: var(--text-4xl); }

.font-normal { font-weight: 400; }
.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }

.text-primary   { color: var(--color-text-primary); }
.text-secondary { color: var(--color-text-secondary); }
.text-muted     { color: var(--color-text-muted); }
.text-accent    { color: var(--color-accent); }
.text-positive  { color: var(--color-positive); }
.text-negative  { color: var(--color-negative); }

.bg-primary   { background: var(--color-bg-primary); }
.bg-secondary { background: var(--color-bg-secondary); }
.bg-tertiary  { background: var(--color-bg-tertiary); }
.bg-elevated  { background: var(--color-bg-elevated); }
.bg-surface   { background: var(--color-bg-surface); }

.rounded-sm { border-radius: var(--radius-sm); }
.rounded-md { border-radius: var(--radius-md); }
.rounded-lg { border-radius: var(--radius-lg); }
.rounded-xl { border-radius: var(--radius-xl); }

.border { border: 1px solid var(--color-border); }
.border-hover:hover { border-color: var(--color-border-hover); }

.w-full { width: 100%; }
.h-full { height: 100%; }

.overflow-hidden { overflow: hidden; }
.overflow-auto   { overflow: auto; }

.relative { position: relative; }
.absolute { position: absolute; }
.sticky   { position: sticky; }

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* ── Components ── */

/* Button */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-sm); font-weight: 600;
  border-radius: var(--radius-md);
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }

.btn-primary {
  background: var(--color-accent);
  color: var(--color-text-inverse);
}
.btn-primary:hover { background: var(--color-accent-hover); }

.btn-secondary {
  background: var(--color-bg-elevated);
  color: var(--color-text-primary);
  border: 1px solid var(--color-border);
}
.btn-secondary:hover { background: var(--color-bg-surface); border-color: var(--color-border-hover); }

.btn-ghost {
  background: transparent;
  color: var(--color-text-secondary);
}
.btn-ghost:hover { color: var(--color-text-primary); background: var(--color-bg-elevated); }

/* Badge */
.badge {
  display: inline-flex; align-items: center;
  padding: 2px var(--space-2);
  font-size: var(--text-xs); font-weight: 600;
  border-radius: var(--radius-sm);
  line-height: 1.4;
}
.badge-positive { background: oklch(20% 0.08 145); color: var(--color-positive); }
.badge-negative { background: oklch(20% 0.08 25); color: var(--color-negative); }
.badge-neutral  { background: var(--color-bg-elevated); color: var(--color-text-muted); }
.badge-blue     { background: oklch(22% 0.08 255); color: var(--color-accent); }

/* Card */
.card {
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-fast);
}
.card:hover { border-color: var(--color-border-hover); }

/* Tabs */
.tabs {
  display: flex; gap: var(--space-1);
  padding: var(--space-1);
  background: var(--color-bg-tertiary);
  border-radius: var(--radius-md);
}
.tab {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-sm); font-weight: 500;
  color: var(--color-text-muted);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  cursor: pointer;
  white-space: nowrap;
}
.tab:hover { color: var(--color-text-secondary); }
.tab.active {
  background: var(--color-bg-elevated);
  color: var(--color-text-primary);
  box-shadow: var(--shadow-sm);
}

/* Sparkline SVG */
.sparkline {
  width: 80px; height: 28px;
}

/* Table */
.data-table th,
.data-table td {
  padding: var(--space-3) var(--space-4);
  text-align: left;
  font-size: var(--text-sm);
  border-bottom: 1px solid var(--color-border);
}
.data-table th {
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  font-size: var(--text-xs);
  background: var(--color-bg-tertiary);
}
.data-table tr:last-child td { border-bottom: none; }
.data-table tbody tr:hover td { background: var(--color-bg-tertiary); }
.data-table .num { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }

/* Navigation */
.nav {
  background: var(--color-bg-secondary);
  border-bottom: 1px solid var(--color-border);
}
.nav-link {
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-sm); font-weight: 500;
  color: var(--color-text-muted);
  border-bottom: 2px solid transparent;
  transition: color var(--transition-fast);
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active { color: var(--color-text-primary); }
.nav-link.active { border-bottom-color: var(--color-accent); }

/* Section header */
.section-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: var(--space-4);
}
.section-title {
  font-size: var(--text-lg); font-weight: 600;
  color: var(--color-text-primary);
}

/* Accordion */
.accordion-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-sm); font-weight: 600;
  color: var(--color-text-secondary);
  background: var(--color-bg-tertiary);
  cursor: pointer;
  transition: background var(--transition-fast);
  border-bottom: 1px solid var(--color-border);
}
.accordion-header:hover { background: var(--color-bg-elevated); }
.accordion-body { display: none; }
.accordion-body.open { display: block; }
.accordion-icon { transition: transform var(--transition-fast); }
.accordion-header.open .accordion-icon { transform: rotate(180deg); }

/* Watchlist row */
.watchlist-row {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-sm);
  border-bottom: 1px solid var(--color-border);
  cursor: pointer;
  transition: background var(--transition-fast);
}
.watchlist-row:hover { background: var(--color-bg-elevated); }
.watchlist-row .sym { font-weight: 600; }
.watchlist-row .last { font-family: var(--font-mono); text-align: right; }
.watchlist-row .chg { font-family: var(--font-mono); text-align: right; }
.watchlist-row .chg-pct { font-family: var(--font-mono); text-align: right; font-weight: 600; }

/* Candlestick chart placeholder */
.chart-container {
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--color-bg-surface); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--color-grey-500); }

/* Responsive */
@media (max-width: 1024px) {
  .container { padding-inline: var(--space-4); }
  .hide-lg { display: none !important; }
}
@media (max-width: 768px) {
  .hide-md { display: none !important; }
  .grid-cols-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-cols-3 { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .hide-sm { display: none !important; }
  .grid-cols-2 { grid-template-columns: 1fr; }
}

