cd /app/output && python3 -c "
# Quick HTML validity check — look for unclosed tags / basic issues
import re
for fname in ['index.html','chart.html','ideas.html','markets.html','brokers.html']:
    with open(fname) as f:
        c = f.read()
    issues = []
    if c.count('<html') != c.count('</html>'): issues.append('html mismatch')
    if c.count('<head>') != c.count('</head>'): issues.append('head mismatch')
    if c.count('<body>') != c.count('</body>'): issues.append('body mismatch')
    if c.count('<div') != c.count('</div>'): issues.append('div mismatch (rough)')
    # Check doctype
    if not c.strip().startswith('<!DOCTYPE html>'): issues.append('missing doctype')
    # Check title
    if '<title>' not in c: issues.append('missing title')
    print(f'{fname}: {issues if issues else \"OK\"}')"
